}

import * as XLSX from 'xlsx';
import { SubsidyRecord, NGOOptions } from '../types';

export const parseExcelFile = async (
  file: File, 
  config: { region: string; worker: string; month: string }
): Promise<SubsidyRecord[]> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });

        // Target the first sheet or one containing "Summary"
        const sheetName = workbook.SheetNames.find(n => n.includes('Summary') || n.includes('總表')) || workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];

        // Convert to JSON starting from row 3 (header=2 in pandas)
        const jsonData: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

        if (jsonData.length < 3) throw new Error("File format too short or invalid.");

        const headers = jsonData[2].map(h => String(h || '').trim());
        const rows = jsonData.slice(3);

        const nameIdx = headers.indexOf('Name') === -1 ? headers.indexOf('姓名') : headers.indexOf('Name');
        const itemIdx = headers.indexOf('Item') === -1 ? headers.indexOf('項目') : headers.indexOf('Item');
        const subtotalIdx = headers.indexOf('Subtotal') === -1 ? headers.indexOf('小計') : headers.indexOf('Subtotal');

        if (nameIdx === -1 || itemIdx === -1) {
          throw new Error("Required columns 'Name' and 'Item' not found.");
        }

        const records: SubsidyRecord[] = [];
        let currentName = '';
        const timestamp = new Date().toLocaleString();

        // Detect funding sources (columns between Item and Subtotal)
        const sourceStartIndex = itemIdx + 2; // Skipping date/memo col if it exists usually
        const sourceEndIndex = subtotalIdx !== -1 ? subtotalIdx : headers.length;
        const fundingSources = headers.slice(sourceStartIndex, sourceEndIndex).filter(s => s && !s.includes('Unnamed'));

        rows.forEach((row, rowIndex) => {
          const rawName = row[nameIdx];
          if (rawName) currentName = String(rawName).trim();

          const itemName = row[itemIdx];
          if (!itemName || String(itemName).includes('Total') || String(itemName).includes('合計')) return;

          fundingSources.forEach((source, sIdx) => {
            const amount = row[sourceStartIndex + sIdx];
            const parsedAmount = typeof amount === 'number' ? amount : parseFloat(String(amount || '0').replace(/,/g, ''));

            if (parsedAmount > 0) {
              records.push({
                id: Math.random().toString(36).substr(2, 9),
                submitTime: timestamp,
                region: config.region,
                worker: config.worker,
                clientName: currentName,
                month: config.month,
                item: String(itemName),
                amount: parsedAmount,
                source: source,
                remarks: 'Batch Import'
              });
            }
          });
        });

        resolve(records);
      } catch (err) {
        reject(err);
      }
    };
    reader.onerror = (err) => reject(err);
    reader.readAsBinaryString(file);
  });
};

import { GoogleGenAI } from "@google/genai";
import { SubsidyRecord } from "../types";

export const getFinancialInsights = async (records: SubsidyRecord[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const summaryData = records.map(r => ({
    client: r.clientName,
    item: r.item,
    amount: r.amount,
    source: r.source
  }));

  const prompt = `Analyze this list of NGO subsidy disbursements and provide a concise summary (under 200 words) in Traditional Chinese. 
  Highlight:
  1. Total amount.
  2. The most common subsidy item.
  3. Any notable funding source contribution.
  4. A brief recommendation for budget tracking.

  Data: ${JSON.stringify(summaryData)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Unable to generate insights at this time.";
  } catch (error) {
    console.error("AI Insights Error:", error);
    return "AI insight engine is currently unavailable.";
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter, Routes, Route, Navigate, Link, useLocation } from 'react-router-dom';
import { LayoutDashboard, FileUp, ListChecks, PlusCircle, LogOut, Info, AlertTriangle, CheckCircle2, Loader2, Sparkles } from 'lucide-react';
