const LoginScreen = ({ onLogin }: { onLogin: () => void }) => {
  const [pass, setPass] = useState('');
  const [error, setError] = useState(false);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (pass === '2025ngo') {
      onLogin();
    } else {
      setError(true);
      setTimeout(() => setError(false), 2000);
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-md p-8 rounded-3xl shadow-2xl">
        <div className="text-center mb-8">
          <div className="inline-block bg-indigo-600 p-4 rounded-3xl text-white mb-4">
            <CheckCircle2 size={40} />
          </div>
          <h1 className="text-2xl font-bold text-slate-900">NGO Verification</h1>
          <p className="text-slate-500">Secure access to subsidy management</p>
        </div>

        <form onSubmit={handleLogin} className="space-y-6">
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">System Passcode</label>
            <input 
              type="password"
              placeholder="Enter passcode"
              className={`w-full px-4 py-4 rounded-2xl bg-slate-50 border focus:ring-2 focus:ring-indigo-500 transition-all outline-none text-center text-lg tracking-[1em] ${
