                  </tr>
                ))}
              </tbody>
            </table>
            {preview.length > 10 && (
              <div className="p-3 bg-slate-50/50 border-t border-slate-100 text-center text-xs text-slate-400 italic">
                ... 以及另外 {preview.length - 10} 筆資料
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

