function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  // 紀錄持久化：初始化時嘗試從 LocalStorage 讀取，若無則使用 Mock
  const [records, setRecords] = useState<SubsidyRecord[]>(() => {
    const saved = localStorage.getItem('ngo_records');
    return saved ? JSON.parse(saved) : MOCK_RECORDS;
  });

  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.DASHBOARD);

  // 當紀錄變動時，同步存回 LocalStorage
  useEffect(() => {
    localStorage.setItem('ngo_records', JSON.stringify(records));
  }, [records]);

  useEffect(() => {
    const auth = localStorage.getItem('ngo_auth');
    if (auth === 'true') setIsLoggedIn(true);
  }, []);

  const handleLogin = () => {
    setIsLoggedIn(true);
    localStorage.setItem('ngo_auth', 'true');
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    localStorage.removeItem('ngo_auth');
  };

  const addRecords = (newRecords: SubsidyRecord[]) => {
    setRecords(prev => [...newRecords, ...prev]);
  };

  const deleteRecord = (id: string) => {
    setRecords(prev => prev.filter(r => r.id !== id));
  };

  if (!isLoggedIn) {
    return <LoginScreen onLogin={handleLogin} />;
  }

  return (
    <HashRouter>
      <div className="flex min-h-screen bg-slate-50">
        <Sidebar activeTab={activeTab} onLogout={handleLogout} />

        <main className="flex-1 ml-64 p-8">
          <header className="mb-8 flex justify-between items-center">
            <div>
              <h1 className="text-2xl font-bold text-slate-900">
                {activeTab === 'dashboard' ? '財務儀表板' : 
                 activeTab === 'import' ? 'Excel 批次匯入' : 
                 activeTab === 'manual' ? '單筆紀錄補登' : '資料紀錄管理'}
              </h1>
              <div className="flex items-center gap-2 mt-1">
                <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                <span className="text-xs font-medium text-slate-400">本地資料存取中...</span>
              </div>
            </div>

            <div className="flex items-center gap-4">
              <div className="text-right">
                <p className="text-sm font-bold text-slate-900">管理員端</p>
                <p className="text-[10px] text-slate-400 uppercase tracking-tighter">內部專屬平台</p>
              </div>
              <div className="w-10 h-10 bg-indigo-100 rounded-full flex items-center justify-center text-indigo-600 font-bold border-2 border-white shadow-sm overflow-hidden">
                NGO
              </div>
            </div>
          </header>

          <Routes>
            <Route path="/dashboard" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.DASHBOARD} /><Dashboard records={records} /></>} />
            <Route path="/import" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.IMPORT} /><ImportTab onImport={addRecords} /></>} />
            <Route path="/manual" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.MANUAL} /><ManualEntry onAdd={(r) => addRecords([r])} /></>} />
            <Route path="/records" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.RECORDS} /><RecordsTable records={records} onDelete={deleteRecord} /></>} />
            <Route path="*" element={<Navigate to="/dashboard" replace />} />
          </Routes>
        </main>
      </div>
    </HashRouter>
  );
}

const NavWatcher = ({ setActive, tab }: { setActive: (t: AppTab) => void, tab: AppTab }) => {
  useEffect(() => {
    setActive(tab);
  }, [setActive, tab]);
  return null;
};

export default App;

