const SettingsPage = ({ options, setOptions }: { options: NGOOptions, setOptions: React.Dispatch<React.SetStateAction<NGOOptions>> }) => {
  const [newItem, setNewItem] = useState("");

  const addItem = (key: keyof NGOOptions) => {
    if (!newItem.trim()) return;
    if (options[key].includes(newItem.trim())) {
      alert("該項目已存在！");
      return;
    }
    setOptions(prev => ({ ...prev, [key]: [...prev[key], newItem.trim()] }));
    setNewItem("");
  };

  const removeItem = (key: keyof NGOOptions, index: number) => {
    setOptions(prev => ({ ...prev, [key]: prev[key].filter((_, i) => i !== index) }));
  };

  const sections: { key: keyof NGOOptions; label: string; desc: string }[] = [
    { key: 'workers', label: '社工人員名單', desc: '用於匯入與補登時的下拉選擇' },
    { key: 'items', label: '補助項目管理', desc: '定義各種核銷類別' },
    { key: 'sources', label: '經費來源管理', desc: '定義撥款單位或勸募專案' },
    { key: 'clients', label: '個案主檔管理', desc: '維護常用個案姓名' },
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-12">
      {sections.map(section => (
        <div key={section.key} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="mb-4">
            <h3 className="font-bold text-slate-900">{section.label}</h3>
            <p className="text-xs text-slate-400">{section.desc}</p>
          </div>
          <div className="flex gap-2 mb-4">
            <input 
              type="text"
              placeholder="新增名稱..."
              className="flex-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              onKeyDown={(e) => { if(e.key === 'Enter') addItem(section.key) }}
              onChange={(e) => setNewItem(e.target.value)}
              value={newItem}
            />
            <button onClick={() => addItem(section.key)} className="bg-indigo-600 text-white p-2 rounded-lg hover:bg-indigo-700">
              <Plus size={20} />
            </button>
          </div>
          <div className="flex flex-wrap gap-2 max-h-48 overflow-y-auto no-scrollbar">
            {options[section.key].map((item, idx) => (
              <span key={idx} className="bg-slate-100 text-slate-700 px-3 py-1.5 rounded-full text-xs font-medium flex items-center gap-1.5 group border border-slate-200">
                {item}
                <button onClick={() => removeItem(section.key, idx)} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                  <X size={14} />
                </button>
              </span>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

