// --- 主要 App 邏輯 ---
function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.DASHBOARD);

  const [records, setRecords] = useState<SubsidyRecord[]>(() => {
    const saved = localStorage.getItem('ngo_records');
    return saved ? JSON.parse(saved) : MOCK_RECORDS;
  });

  const [options, setOptions] = useState<NGOOptions>(() => {
    const saved = localStorage.getItem('ngo_settings');
    return saved ? JSON.parse(saved) : NGO_CONFIG;
  });

  useEffect(() => { localStorage.setItem('ngo_records', JSON.stringify(records)); }, [records]);
  useEffect(() => { localStorage.setItem('ngo_settings', JSON.stringify(options)); }, [options]);
  useEffect(() => { if (localStorage.getItem('ngo_auth') === 'true') setIsLoggedIn(true); }, []);

  const handleLogin = () => { setIsLoggedIn(true); localStorage.setItem('ngo_auth', 'true'); };
  const handleLogout = () => { setIsLoggedIn(false); localStorage.removeItem('ngo_auth'); };

  if (!isLoggedIn) return <LoginScreen onLogin={handleLogin} />;

  return (
    <HashRouter>
      <div className="flex min-h-screen bg-slate-50">
        <Sidebar activeTab={activeTab} onLogout={handleLogout} />
        <main className="flex-1 ml-64 p-8">
          <header className="mb-8 flex justify-between items-center">
            <h1 className="text-2xl font-bold text-slate-900">{activeTab.toUpperCase()}</h1>
            <div className="px-4 py-1.5 bg-white border rounded-full text-xs font-bold text-indigo-600 shadow-sm">VER 6.0 | SYSTEM READY</div>
          </header>
          <Routes>
            <Route path="/dashboard" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.DASHBOARD} /><Dashboard records={records} /></>} />
            <Route path="/import" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.IMPORT} /><ImportTab onImport={(r) => setRecords(prev => [...r, ...prev])} options={options} /></>} />
            <Route path="/manual" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.MANUAL} /><ManualEntry onAdd={(r) => setRecords(prev => [r, ...prev])} options={options} /></>} />
            <Route path="/records" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.RECORDS} /><RecordsTable records={records} onDelete={(id) => setRecords(p => p.filter(r => r.id !== id))} onClearAll={() => setRecords([])} /></>} />
            <Route path="/settings" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.SETTINGS} /><SettingsPage options={options} setOptions={setOptions} /></>} />
            <Route path="*" element={<Navigate to="/dashboard" replace />} />
          </Routes>
        </main>
      </div>
    </HashRouter>
  );
}

