/**
 * 將本地紀錄同步至 Google Sheets
 * 需配合 Google Apps Script 使用
 */
export const syncToGoogleSheets = async (url: string, records: SubsidyRecord[]): Promise<boolean> => {
  if (!url) return false;

  try {
    // 準備發送的資料格式
    const payload = records.map(r => ({
      timestamp: r.submitTime,
      region: r.region,
      worker: r.worker,
      clientName: r.clientName,
      month: r.month,
      item: r.item,
      amount: r.amount,
      source: r.source,
      remarks: r.remarks
    }));

    // 使用 fetch 發送 POST 請求
    // 注意：Google Apps Script 通常需要使用 no-cors 模式，或者在 GAS 端處理 CORS
    const response = await fetch(url, {
      method: 'POST',
      mode: 'no-cors', // 避免跨網域預檢請求失敗
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        action: 'sync_all',
        data: payload
      })
    });

    // 由於 no-cors 模式無法讀取 response body，我們假設發送成功即為 true
    return true;
  } catch (error) {
    console.error("Sync to Sheets Error:", error);
    return false;
  }
};

