const RecordsTable = ({ records, onDelete, onClearAll, syncUrl }: { records: SubsidyRecord[], onDelete: (id: string) => void, onClearAll: () => void, syncUrl?: string }) => {
  const [syncing, setSyncing] = useState(false);

  const handleSync = async () => {
    if (!syncUrl) {
      alert("請先在「系統設定」中配置 Google Apps Script URL。");
      return;
    }
    setSyncing(true);
    const success = await syncToGoogleSheets(syncUrl, records);
    setSyncing(false);
    if (success) alert("已將所有數據推送到雲端試算表！");
    else alert("同步失敗，請檢查網路或 URL 設定。");
  };

  const exportToExcel = () => {
    if (records.length === 0) return;
    const worksheet = XLSX.utils.json_to_sheet(records.map(r => ({
      '提交時間': r.submitTime,
      '區域': r.region,
      '社工': r.worker,
      '個案姓名': r.clientName,
      '核銷月份': r.month,
      '補助項目': r.item,
      '金額': r.amount,
      '經費來源': r.source,
      '備註': r.remarks
    })));
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Records");
    XLSX.writeFile(workbook, `NGO_Records_${new Date().toISOString().slice(0,10)}.xlsx`);
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
      <div className="p-6 border-b flex justify-between items-center bg-slate-50/50">
        <div><h2 className="text-xl font-bold">歷史核銷數據</h2><p className="text-slate-500 text-sm">點擊同步按鈕可將資料傳送到 Google Sheets。</p></div>
        <div className="flex gap-2">
          {records.length > 0 && (
            <>
              <button 
                onClick={handleSync} 
                disabled={syncing}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-50 text-emerald-600 rounded-xl text-sm font-bold hover:bg-emerald-100 transition-all border border-emerald-100 disabled:opacity-50"
              >
                {syncing ? <Loader2 size={16} className="animate-spin" /> : <CloudUpload size={16} />} 
                同步至雲端
              </button>
              <button onClick={exportToExcel} className="flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl text-sm font-bold hover:bg-indigo-100">
                <Download size={16} /> 匯出
              </button>
              <button onClick={() => { if(window.confirm("確定清空？")) onClearAll() }} className="p-2 text-red-500 hover:bg-red-50 rounded-lg"><RotateCcw size={20} /></button>
            </>
          )}
        </div>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead className="bg-slate-50 text-slate-500">
            <tr><th className="px-6 py-4 text-left">個案</th><th className="px-6 py-4 text-left">來源</th><th className="px-6 py-4 text-left">項目</th><th className="px-6 py-4 text-right">金額</th><th className="px-6 py-4 text-center">操作</th></tr>
          </thead>
          <tbody className="divide-y">
            {records.length === 0 ? <tr><td colSpan={5} className="p-12 text-center text-slate-400 italic">無紀錄</td></tr> :
              records.map(r => <tr key={r.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4 font-bold">{r.clientName}</td><td className="px-6 py-4 text-indigo-600 font-medium">{r.source}</td><td className="px-6 py-4 text-slate-600">{r.item}</td><td className="px-6 py-4 text-right font-bold text-slate-900">${r.amount.toLocaleString()}</td>
                <td className="px-6 py-4 text-center">
                  <button onClick={() => { if(window.confirm(`刪除 ${r.clientName}?`)) onDelete(r.id) }} className="p-2 text-slate-300 hover:text-red-600 transition-colors"><Trash2 size={18} /></button>
                </td>
              </tr>)}
          </tbody>
        </table>
      </div>
    </div>
  );
};

// --- 主要 App 邏輯 ---
function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.DASHBOARD);

  const [records, setRecords] = useState<SubsidyRecord[]>(() => {
    const saved = localStorage.getItem('ngo_records');
    return saved ? JSON.parse(saved) : MOCK_RECORDS;
  });

  const [options, setOptions] = useState<NGOOptions>(() => {
    const saved = localStorage.getItem('ngo_settings');
    return saved ? JSON.parse(saved) : NGO_CONFIG;
  });

  useEffect(() => { localStorage.setItem('ngo_records', JSON.stringify(records)); }, [records]);
  useEffect(() => { localStorage.setItem('ngo_settings', JSON.stringify(options)); }, [options]);
  useEffect(() => { if (localStorage.getItem('ngo_auth') === 'true') setIsLoggedIn(true); }, []);

  const handleLogin = () => { setIsLoggedIn(true); localStorage.setItem('ngo_auth', 'true'); };
  const handleLogout = () => { setIsLoggedIn(false); localStorage.removeItem('ngo_auth'); };

  if (!isLoggedIn) return <LoginScreen onLogin={handleLogin} />;

  return (
    <HashRouter>
      <div className="flex min-h-screen bg-slate-50">
        <Sidebar activeTab={activeTab} onLogout={handleLogout} sheetUrl="https://docs.google.com/spreadsheets/d/1nMKA3Vg7Tb7hudpuJiG4bZiKCz29yLCguOiJZC3f7bk/edit" />
        <main className="flex-1 ml-64 p-8">
          <header className="mb-8 flex justify-between items-center">
            <h1 className="text-2xl font-bold text-slate-900">{activeTab.toUpperCase()}</h1>
            <div className="flex items-center gap-3">
              <div className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold border ${options.syncUrl ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'bg-slate-100 text-slate-400 border-slate-200'}`}>
                {options.syncUrl ? <CloudCheck size={12}/> : <CloudOff size={12}/>}
                {options.syncUrl ? 'CLOUD READY' : 'LOCAL ONLY'}
              </div>
              <div className="px-4 py-1.5 bg-white border rounded-full text-xs font-bold text-indigo-600 shadow-sm">NGO SYSTEM v7.0</div>
            </div>
          </header>
          <Routes>
            <Route path="/dashboard" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.DASHBOARD} /><Dashboard records={records} /></>} />
            <Route path="/import" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.IMPORT} /><ImportTab onImport={(r) => setRecords(prev => [...r, ...prev])} options={options} /></>} />
            <Route path="/manual" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.MANUAL} /><ManualEntry onAdd={(r) => setRecords(prev => [r, ...prev])} options={options} /></>} />
            <Route path="/records" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.RECORDS} /><RecordsTable records={records} onDelete={(id) => setRecords(p => p.filter(r => r.id !== id))} onClearAll={() => setRecords([])} syncUrl={options.syncUrl} /></>} />
            <Route path="/settings" element={<><NavWatcher setActive={setActiveTab} tab={AppTab.SETTINGS} /><SettingsPage options={options} setOptions={setOptions} /></>} />
            <Route path="*" element={<Navigate to="/dashboard" replace />} />
          </Routes>
        </main>
      </div>
    </HashRouter>
  );
}

