            <button type="button" onClick={() => setShow(!show)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 p-2 hover:text-indigo-500 transition-colors">{show ? <EyeOff size={22}/> : <Eye size={22}/>}</button>
          </div>
          <button type="submit" className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-bold text-lg hover:shadow-2xl hover:bg-indigo-700 transition-all active:scale-[0.98]">
            進入系統
          </button>
        </form>
      </div>
    </div>
  );
};

const NavWatcher = ({ setActive, tab }: { setActive: (t: AppTab) => void, tab: AppTab }) => {
  useEffect(() => { setActive(tab); }, [setActive, tab]);
  return null;
};

const ImportTab = ({ onImport, options }: { onImport: (newRecords: SubsidyRecord[]) => void, options: NGOOptions }) => {
  const [file, setFile] = useState<File | null>(null);
  const [region, setRegion] = useState(options.regions[0]);
  const [worker, setWorker] = useState(options.workers[0]);
  const [month, setMonth] = useState('2025-01');
  const [loading, setLoading] = useState(false);
  const [preview, setPreview] = useState<SubsidyRecord[]>([]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) setFile(e.target.files[0]);
  };

  const processFile = async () => {
    if (!file) return;
    setLoading(true);
    try {
      const results = await parseExcelFile(file, { region, worker, month });
      setPreview(results.map(r => ({ ...r, id: generateId() })));
    } catch (err: any) {
      alert("解析失敗: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  const confirmImport = () => {
    onImport(preview);
    setPreview([]);
    setFile(null);
    alert("已成功匯入！建議前往「紀錄查詢」分頁點擊雲端同步。");
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
      <div className="p-6 border-b border-slate-100">
        <h2 className="text-xl font-bold">批次匯入撥款名冊</h2>
        <p className="text-slate-500 text-sm">請上傳 Excel 檔，系統將自動解析姓名與金額。</p>
      </div>
      <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">區域</label>
          <select className="w-full bg-slate-50 border rounded-lg px-3 py-2 text-sm outline-none" value={region} onChange={(e) => setRegion(e.target.value)}>
            {options.regions.map(r => <option key={r} value={r}>{r}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">社工人員</label>
          <select className="w-full bg-slate-50 border rounded-lg px-3 py-2 text-sm outline-none" value={worker} onChange={(e) => setWorker(e.target.value)}>
            {options.workers.map(w => <option key={w} value={w}>{w}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">月份</label>
          <input type="month" className="w-full bg-slate-50 border rounded-lg px-3 py-2 text-sm outline-none" value={month} onChange={(e) => setMonth(e.target.value)} />
        </div>
      </div>
      <div className="px-6 pb-6">
        <div className="border-2 border-dashed border-slate-200 rounded-2xl p-10 text-center bg-slate-50/50 hover:bg-slate-50 cursor-pointer transition-all">
          <input type="file" id="excel-upload" className="hidden" accept=".xlsx, .xls" onChange={handleFileChange}/>
          <label htmlFor="excel-upload" className="cursor-pointer flex flex-col items-center">
            <div className="bg-white p-4 rounded-2xl shadow-sm mb-4">
              <FileUp size={40} className="text-indigo-500" />
            </div>
            <p className="text-slate-900 font-bold">{file ? file.name : '點擊選擇名冊檔案'}</p>
            <p className="text-slate-400 text-xs mt-1">支援 .xlsx, .xls 格式</p>
          </label>
        </div>
        {file && !preview.length && (
          <button onClick={processFile} disabled={loading} className="mt-6 w-full bg-indigo-600 text-white py-4 rounded-2xl font-bold hover:bg-indigo-700 shadow-xl shadow-indigo-100 flex items-center justify-center gap-2">
            {loading ? <Loader2 className="animate-spin" /> : <Sparkles size={20}/>}
            {loading ? '解析中...' : '開始自動解析'}
          </button>
        )}
      </div>
      {preview.length > 0 && (
        <div className="p-6 bg-slate-50 border-t">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-bold flex items-center gap-2">
              <CheckCircle2 size={18} className="text-emerald-500" />
              解析結果（共 {preview.length} 筆）
            </h3>
            <div className="flex gap-2">
              <button onClick={() => setPreview([])} className="bg-white px-4 py-2 rounded-xl border text-sm font-medium hover:bg-slate-50">取消</button>
              <button onClick={confirmImport} className="bg-emerald-600 text-white px-6 py-2 rounded-xl text-sm font-bold shadow-lg shadow-emerald-100">確認匯入</button>
            </div>
          </div>
          <div className="max-h-64 overflow-y-auto rounded-xl border bg-white shadow-sm">
            <table className="w-full text-xs">
              <thead className="bg-slate-50 sticky top-0"><tr><th className="p-3 text-left">個案姓名</th><th className="p-3 text-left">補助項目</th><th className="p-3 text-right">核銷金額</th></tr></thead>
              <tbody className="divide-y">{preview.map((r, i) => <tr key={i}>
                <td className="p-3 font-medium">{r.clientName}</td><td className="p-3 text-slate-500">{r.item}</td><td className="p-3 text-right font-bold text-slate-900">${r.amount.toLocaleString()}</td>
              </tr>)}</tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

payload.text:
### 後續操作指南：

為了讓資料能真的進到試算表，您需要完成以下一次性設定：

1.  **開啟 Google Apps Script**：在您的試算表中，點擊 **「延伸功能」 > 「Apps Script」**。
2.  **貼上以下腳本**：
    ```javascript
    function doPost(e) {
      var payload = JSON.parse(e.postData.contents);
      var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheets()[0]; // 存到第一個分頁

      if (payload.action === 'sync_all') {
        payload.data.forEach(function(row) {
          sheet.appendRow([
            row.timestamp, row.worker, row.clientName, row.month, 
            row.item, row.amount, row.source, row.remarks
          ]);
        });
        return ContentService.createTextOutput("Sync Success");
      }
    }
    ```
3.  **部署 Web 應用程式**：點擊 **「部署」 > 「新部署」**，類型選擇「網頁應用程式」，並設定為 **「任何人」** 都能存取。
4.  **貼回系統設定**：將產出的 `https://script.google.com/.../exec` 網址貼回到本系統的 **「系統設定」** 分頁中。

這樣一來，當您在系統點擊「同步至雲端」時，所有資料就會自動排好隊，整齊地出現在您的 Google 試算表中了！

