import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter, Routes, Route, Navigate, Link } from 'react-router-dom';
import { 
  LayoutDashboard, FileUp, ListChecks, PlusCircle, LogOut, Info, 
  CheckCircle2, Loader2, Sparkles, Trash2, Eye, EyeOff, RotateCcw, 
  Settings as SettingsIcon, Download, Plus, X, CloudUpload, ExternalLink, CloudCheck, CloudOff, ListOrdered
} from 'lucide-react';
import * as XLSX from 'xlsx';
import { NGO_CONFIG, MOCK_RECORDS } from './constants';
import { SubsidyRecord, AppTab, NGOOptions } from './types';
import { parseExcelFile } from './services/excelService';
import { getFinancialInsights } from './services/geminiService';
import { syncToGoogleSheets } from './services/googleSheetsService';

const generateId = () => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

// --- 元件：側邊導覽列 ---
const Sidebar = ({ activeTab, onLogout, sheetUrl }: { activeTab: string, onLogout: () => void, sheetUrl?: string }) => {
  const menuItems = [
    { id: AppTab.DASHBOARD, label: '儀表板', icon: LayoutDashboard },
    { id: AppTab.IMPORT, label: '批次匯入', icon: FileUp },
    { id: AppTab.MANUAL, label: '單筆補登', icon: PlusCircle },
    { id: AppTab.RECORDS, label: '紀錄查詢', icon: ListChecks },
    { id: AppTab.SETTINGS, label: '系統設定', icon: SettingsIcon },
  ];

  return (
    <div className="w-64 bg-slate-900 h-screen fixed left-0 top-0 text-white flex flex-col z-50">
      <div className="p-6 border-b border-slate-800">
        <h1 className="text-xl font-bold flex items-center gap-2">
          <span className="bg-indigo-500 p-1.5 rounded-lg text-white">NGO</span>
          核銷系統
        </h1>
        <p className="text-xs text-slate-400 mt-1 uppercase tracking-wider">補助驗證系統 v7.5</p>
      </div>
      <nav className="flex-1 mt-6 px-4 space-y-2">
        {menuItems.map((item) => (
          <Link
            key={item.id}
            to={`/${item.id}`}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
              activeTab === item.id 
                ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' 
                : 'text-slate-400 hover:bg-slate-800 hover:text-white'
            }`}
          >
            <item.icon size={20} />
            <span className="font-medium">{item.label}</span>
          </Link>
        ))}
        {sheetUrl && (
          <a 
            href={sheetUrl} 
            target="_blank" 
            rel="noopener noreferrer"
            className="flex items-center gap-3 px-4 py-3 rounded-xl text-emerald-400 hover:bg-emerald-500/10 transition-all mt-4 border border-emerald-500/20"
          >
            <ExternalLink size={20} />
            <span className="font-medium">開啟雲端試算表</span>
          </a>
        )}
      </nav>
      <div className="p-4 border-t border-slate-800">
        <button onClick={onLogout} className="flex items-center gap-3 px-4 py-3 rounded-xl text-slate-400 hover:bg-red-500/10 hover:text-red-400 transition-all w-full">
          <LogOut size={20} />
          <span className="font-medium">登出系統</span>
        </button>
      </div>
    </div>
  );
};

// --- 元件：系統設定 ---
const SettingsPage = ({ options, setOptions }: { options: NGOOptions, setOptions: React.Dispatch<React.SetStateAction<NGOOptions>> }) => {
  const [newItem, setNewItem] = useState("");

  const addItem = (key: keyof NGOOptions) => {
    if (key === 'syncUrl') return;
    if (!newItem.trim()) return;
    if ((options[key] as string[]).includes(newItem.trim())) {
      alert("該項目已存在！");
      return;
    }
    setOptions(prev => ({ ...prev, [key]: [...(prev[key] as string[]), newItem.trim()] }));
    setNewItem("");
  };

  const removeItem = (key: keyof NGOOptions, index: number) => {
    if (key === 'syncUrl') return;
    setOptions(prev => ({ ...prev, [key]: (prev[key] as string[]).filter((_, i) => i !== index) }));
  };

  const columnOrder = [
    "提交時間", "社工", "個案姓名", "核銷月份", "補助項目", "金額", "經費來源", "備註"
  ];

  return (
    <div className="space-y-6 pb-12">
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <div className="flex items-center gap-2 mb-4">
          <CloudUpload className="text-indigo-500" size={24} />
          <h3 className="font-bold text-slate-900 text-lg">Google 試算表同步設定</h3>
        </div>
        <div className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">GAS Web App URL</label>
            <input 
              type="text"
              placeholder="https://script.google.com/macros/s/.../exec"
              className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none font-mono"
              value={options.syncUrl || ''}
              onChange={(e) => setOptions(prev => ({ ...prev, syncUrl: e.target.value }))}
            />
            <p className="text-xs text-slate-400 mt-2 leading-relaxed">
              請部署 Google Apps Script 並將產出的網址貼上。系統將透過此 Webhook 將本地資料同步至您的試算表。
            </p>
          </div>

          <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
            <h4 className="text-xs font-bold text-slate-500 uppercase flex items-center gap-2 mb-3">
              <ListOrdered size={14} /> 試算表欄位順序指引 (請確保標題列順序一致)
            </h4>
            <div className="flex flex-wrap gap-2">
              {columnOrder.map((col, i) => (
                <div key={i} className="flex items-center bg-white border border-slate-200 rounded-lg px-3 py-1.5 shadow-sm">
                  <span className="text-[10px] font-bold text-indigo-500 w-4">{String.fromCharCode(65 + i)}</span>
                  <span className="text-xs font-medium text-slate-700 border-l pl-2 ml-1">{col}</span>
                </div>
              ))}
            </div>
            <p className="text-[10px] text-slate-400 mt-3 italic">* 若順序不對，同步後的資料會錯位，請務必先設定好試算表第一列標題。</p>
          </div>

          <a 
            href="https://docs.google.com/spreadsheets/d/1nMKA3Vg7Tb7hudpuJiG4bZiKCz29yLCguOiJZC3f7bk/edit" 
            target="_blank" 
            rel="noopener noreferrer"
            className="inline-flex items-center gap-2 text-indigo-600 text-sm font-medium hover:underline"
          >
            <ExternalLink size={16} /> 前往目前對接的試算表
          </a>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {[
          { key: 'workers', label: '社工人員', desc: '匯入時的下拉選單內容' },
          { key: 'items', label: '補助項目', desc: '定義核銷類別' },
          { key: 'sources', label: '經費來源', desc: '定義撥款專案' },
          { key: 'clients', label: '個案主檔', desc: '常用個案姓名' },
        ].map(section => (
          <div key={section.key} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
            <div className="mb-4">
              <h3 className="font-bold text-slate-900">{section.label}</h3>
              <p className="text-xs text-slate-400">{section.desc}</p>
            </div>
            <div className="flex gap-2 mb-4">
              <input 
                type="text"
                placeholder="新增..."
                className="flex-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none"
                onKeyDown={(e) => { if(e.key === 'Enter') addItem(section.key as keyof NGOOptions) }}
                onChange={(e) => setNewItem(e.target.value)}
                value={newItem}
              />
              <button onClick={() => addItem(section.key as keyof NGOOptions)} className="bg-indigo-600 text-white p-2 rounded-lg hover:bg-indigo-700 transition-colors">
                <Plus size={20} />
              </button>
            </div>
            <div className="flex flex-wrap gap-2 max-h-40 overflow-y-auto no-scrollbar">
              {(options[section.key as keyof NGOOptions] as string[]).map((item, idx) => (
                <span key={idx} className="bg-slate-100 text-slate-700 px-3 py-1.5 rounded-full text-xs font-medium flex items-center gap-1.5 group border border-slate-200">
                  {item}
                  <button onClick={() => removeItem(section.key as keyof NGOOptions, idx)} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                    <X size={14} />
                  </button>
                </span>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

// --- 元件：儀表板 ---
const Dashboard = ({ records }: { records: SubsidyRecord[] }) => {
  const totalAmount = useMemo(() => records.reduce((sum, r) => sum + r.amount, 0), [records]);
  const [insight, setInsight] = useState<string>('');
  const [loadingInsight, setLoadingInsight] = useState(false);

  const stats = useMemo(() => {
    const clients = new Set(records.map(r => r.clientName)).size;
    const sources = new Set(records.map(r => r.source)).size;
    return { clients, sources };
  }, [records]);

  const generateAIInsight = async () => {
    if (records.length === 0) return;
    setLoadingInsight(true);
    const result = await getFinancialInsights(records);
    setInsight(result);
    setLoadingInsight(false);
  };

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium">總核銷金額</p>
          <p className="text-3xl font-bold text-slate-900 mt-2">${totalAmount.toLocaleString()}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium">個案總數</p>
          <p className="text-3xl font-bold text-slate-900 mt-2">{stats.clients}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium">資金來源</p>
          <p className="text-3xl font-bold text-slate-900 mt-2">{stats.sources}</p>
        </div>
      </div>
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-semibold flex items-center gap-2">
            <Sparkles className="text-indigo-500" size={20} />
            AI 財務專家洞察
          </h2>
          <button onClick={generateAIInsight} disabled={loadingInsight || records.length === 0} className="text-xs bg-indigo-50 text-indigo-600 px-3 py-1.5 rounded-full font-medium hover:bg-indigo-100 disabled:opacity-50">
            {loadingInsight ? '分析中...' : '重新生成報告'}
          </button>
        </div>
        {loadingInsight ? (
          <div className="flex flex-col items-center py-8"><Loader2 className="animate-spin text-indigo-500 mb-2" /><p className="text-sm text-slate-500">正在處理數據...</p></div>
        ) : insight ? (
          <div className="bg-slate-50 p-4 rounded-xl text-slate-700 whitespace-pre-wrap text-sm border border-slate-100 leading-relaxed">{insight}</div>
        ) : (
          <div className="text-center py-8 text-slate-400 text-sm italic">點擊按鈕獲取 AI 的預算洞察與建議。</div>
        )}
      </div>
    </div>
  );
};

// --- 紀錄查詢表格 ---
const RecordsTable = ({ records, onDelete, onClearAll, syncUrl }: { records: SubsidyRecord[], onDelete: (id: string) => void, onClearAll: () => void, syncUrl?: string }) => {
  const [syncing, setSyncing] = useState(false);

  const handleSync = async () => {
    if (!syncUrl) {
      alert("請先在「系統設定」中配置 Google Apps Script URL。");
      return;
    }
    setSyncing(true);
    const success = await syncToGoogleSheets(syncUrl, records);
    setSyncing(false);
    if (success) alert("已將所有數據推送到雲端試算表！");
    else alert("同步失敗，請檢查 URL 設定或權限。");
  };

  const exportToExcel = () => {
    if (records.length === 0) return;
    const worksheet = XLSX.utils.json_to_sheet(records.map(r => ({
      '提交時間': r.submitTime,
      '區域': r.region,
      '社工': r.worker,
      '個案姓名': r.clientName,
      '核銷月份': r.month,
      '補助項目': r.item,
      '金額': r.amount,
      '經費來源': r.source,
      '備註': r.remarks
    })));
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Records");
    XLSX.writeFile(workbook, `NGO_Records_${new Date().toISOString().slice(0,10)}.xlsx`);
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
      <div className="p-6 border-b flex justify-between items-center bg-slate-50/50">
        <div><h2 className="text-xl font-bold">歷史核銷數據</h2><p className="text-slate-500 text-sm">點擊同步按鈕可將資料傳送到雲端。</p></div>
        <div className="flex gap-2">
          {records.length > 0 && (
            <>
              <button 
                onClick={handleSync} 
                disabled={syncing}
                className="flex items-center gap-2 px-4 py-2 bg-emerald-50 text-emerald-600 rounded-xl text-sm font-bold hover:bg-emerald-100 transition-all border border-emerald-100 disabled:opacity-50"
              >
                {syncing ? <Loader2 size={16} className="animate-spin" /> : <CloudUpload size={16} />} 
                同步至雲端
              </button>
              <button onClick={exportToExcel} className="flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl text-sm font-bold hover:bg-indigo-100">
                <Download size={16} /> 匯出
              </button>
              <button onClick={() => { if(window.confirm("確定要清空本地所有紀錄嗎？")) onClearAll() }} className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors"><RotateCcw size={20} /></button>
            </>
          )}
        </div>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead className="bg-slate-50 text-slate-500">
            <tr><th className="px-6 py-4 text-left">個案</th><th className="px-6 py-4 text-left">來源</th><th className="px-6 py-4 text-left">項目</th><th className="px-6 py-4 text-right">金額</th><th className="px-6 py-4 text-center">操作</th></tr>
          </thead>
          <tbody className="divide-y">
            {records.length === 0 ? <tr><td colSpan={5} className="p-12 text-center text-slate-400 italic">目前無資料</td></tr> :
              records.map(r => <tr key={r.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4 font-bold text-slate-900">{r.clientName}</td>
