/**
 * 將本地紀錄同步至 Google Sheets
 * 欄位順序：時間, 區域, 社工, 歸屬區域, 個案, 月份, 項目, 金額, 來源, 備註
 */
export const syncToGoogleSheets = async (url: string, records: SubsidyRecord[]): Promise<boolean> => {
  if (!url) return false;

  try {
    const payload = records.map(r => ({
      timestamp: r.submitTime,
      region: r.region,
      worker: r.worker,
      belongingRegion: r.belongingRegion,
      clientName: r.clientName,
      month: r.month,
      item: r.item,
      amount: r.amount,
      source: r.source,
      remarks: r.remarks
    }));

    await fetch(url, {
      method: 'POST',
      mode: 'no-cors',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        action: 'sync_all',
        data: payload
      })
    });

    return true;
  } catch (error) {
    console.error("Sync to Sheets Error:", error);
    return false;
  }
};

function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

import * as XLSX from 'xlsx';
import { SubsidyRecord } from '../types';

export const parseExcelFile = async (
  file: File, 
  config: { region: string; worker: string; belongingRegion: string; month: string }
): Promise<SubsidyRecord[]> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = workbook.SheetNames.find(n => n.includes('Summary') || n.includes('總表') || n.includes('彙總')) || workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const jsonData: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

        if (jsonData.length < 3) throw new Error("檔案格式無效。");

        const headers = jsonData[2].map(h => String(h || '').trim());
        const rows = jsonData.slice(3);

        const nameIdx = headers.indexOf('姓名') === -1 ? headers.indexOf('Name') : headers.indexOf('姓名');
        const itemIdx = headers.indexOf('項目') === -1 ? headers.indexOf('Item') : headers.indexOf('項目');
        const subtotalIdx = headers.indexOf('小計') === -1 ? headers.indexOf('Subtotal') : headers.indexOf('小計');

        if (nameIdx === -1 || itemIdx === -1) {
          throw new Error("找不到必要欄位。");
        }

        const records: SubsidyRecord[] = [];
        let currentName = '';
        const timestamp = new Date().toLocaleString();

        const sourceStartIndex = itemIdx + 2; 
        const sourceEndIndex = subtotalIdx !== -1 ? subtotalIdx : headers.length;
        const fundingSources = headers.slice(sourceStartIndex, sourceEndIndex).filter(s => s && !s.includes('Unnamed') && s !== 'nan');

        rows.forEach((row) => {
          const rawName = row[nameIdx];
          if (rawName) currentName = String(rawName).trim();

          const itemName = row[itemIdx];
          if (!itemName || String(itemName).includes('Total') || String(itemName).includes('合計')) return;

          fundingSources.forEach((source, sIdx) => {
            const amount = row[sourceStartIndex + sIdx];
            const parsedAmount = typeof amount === 'number' ? amount : parseFloat(String(amount || '0').replace(/,/g, ''));

            if (parsedAmount > 0) {
              records.push({
                id: Math.random().toString(36).substr(2, 9),
                submitTime: timestamp,
                region: config.region,
                worker: config.worker,
                belongingRegion: config.belongingRegion,
                clientName: currentName,
                month: config.month,
                item: String(itemName),
                amount: parsedAmount,
                source: source,
                remarks: '批次匯入'
              });
            }
          });
        });

        resolve(records);
      } catch (err) {
        reject(err);
      }
    };
    reader.onerror = (err) => reject(err);
    reader.readAsBinaryString(file);
  });
};

