const SettingsPage = ({ options, setOptions }: { options: NGOOptions, setOptions: React.Dispatch<React.SetStateAction<NGOOptions>> }) => {
  const [inputValues, setInputValues] = useState<Record<string, string>>({});

  const addItem = (key: keyof NGOOptions) => {
    const val = inputValues[key]?.trim();
    if (!val) return;
    if ((options[key] as string[]).includes(val)) {
      alert("該項目已存在！");
      return;
    }
    setOptions(prev => ({ ...prev, [key]: [...(prev[key] as string[]), val] }));
    setInputValues(prev => ({ ...prev, [key]: '' }));
  };

  const removeItem = (key: keyof NGOOptions, index: number) => {
    setOptions(prev => ({ ...prev, [key]: (prev[key] as string[]).filter((_, i) => i !== index) }));
  };

  const columnOrder = [
    "提交時間", "區域", "社工姓名", "歸屬區域", "個案姓名", "補助月份", "補助項目", "金額", "經費來源", "備註"
  ];

  const sections = [
    { key: 'regions', label: '區域', desc: '主要服務中心' },
    { key: 'workers', label: '社工姓名', desc: '負責執行的社工' },
    { key: 'belongingRegions', label: '歸屬區域', desc: '特定專案或小組區域' },
    { key: 'clients', label: '個案姓名', desc: '補助對象主檔' },
    { key: 'items', label: '補助項目', desc: '費用核銷類別' },
    { key: 'sources', label: '經費來源', desc: '經費撥款單位/專案' },
  ];

  return (
    <div className="space-y-6 pb-12">
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <div className="flex items-center gap-2 mb-4">
          <CloudUpload className="text-indigo-500" size={24} />
          <h3 className="font-bold text-slate-900 text-lg">Google 試算表同步設定</h3>
        </div>
        <div className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">GAS Web App URL</label>
            <input 
              type="text"
              placeholder="https://script.google.com/macros/s/.../exec"
              className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none font-mono"
              value={options.syncUrl || ''}
              onChange={(e) => setOptions(prev => ({ ...prev, syncUrl: e.target.value }))}
            />
          </div>

          <div className="bg-slate-50 p-4 rounded-xl border border-slate-100">
            <h4 className="text-xs font-bold text-slate-500 uppercase flex items-center gap-2 mb-3">
              <ListOrdered size={14} /> 雲端試算表標題列順序 (請務必按此順序建立第一列)
            </h4>
            <div className="flex flex-wrap gap-2">
              {columnOrder.map((col, i) => (
                <div key={i} className="flex items-center bg-white border border-slate-200 rounded-lg px-3 py-1.5 shadow-sm">
                  <span className="text-[10px] font-bold text-indigo-500 w-4">{String.fromCharCode(65 + i)}</span>
                  <span className="text-xs font-medium text-slate-700 border-l pl-2 ml-1">{col}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {sections.map(section => (
          <div key={section.key} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col">
            <div className="mb-4">
              <h3 className="font-bold text-slate-900">{section.label}</h3>
              <p className="text-[10px] text-slate-400">{section.desc}</p>
            </div>
            <div className="flex gap-2 mb-4">
              <input 
                type="text"
                placeholder="新增..."
                className="flex-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none"
                value={inputValues[section.key] || ''}
                onChange={(e) => setInputValues({...inputValues, [section.key]: e.target.value})}
                onKeyDown={(e) => { if(e.key === 'Enter') addItem(section.key as keyof NGOOptions) }}
              />
              <button onClick={() => addItem(section.key as keyof NGOOptions)} className="bg-indigo-600 text-white p-2 rounded-lg hover:bg-indigo-700"><Plus size={18} /></button>
            </div>
            <div className="flex flex-wrap gap-2 max-h-48 overflow-y-auto no-scrollbar">
              {(options[section.key as keyof NGOOptions] as string[]).map((item, idx) => (
                <span key={idx} className="bg-slate-100 text-slate-700 px-3 py-1 rounded-full text-[11px] font-medium flex items-center gap-1.5 group border border-slate-200">
                  {item}
                  <button onClick={() => removeItem(section.key as keyof NGOOptions, idx)} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                    <X size={12} />
                  </button>
                </span>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

