const ImportTab = ({ onImport, options }: { onImport: (newRecords: SubsidyRecord[]) => void, options: NGOOptions }) => {
  const [file, setFile] = useState<File | null>(null);
  const [region, setRegion] = useState(options.regions[0] || '');
  const [worker, setWorker] = useState(options.workers[0] || '');
  const [belongingRegion, setBelongingRegion] = useState(options.belongingRegions[0] || '');
  const [month, setMonth] = useState('2025-01');
  const [loading, setLoading] = useState(false);
  const [preview, setPreview] = useState<SubsidyRecord[]>([]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) setFile(e.target.files[0]);
  };

  const processFile = async () => {
    if (!file) return;
    setLoading(true);
    try {
      const results = await parseExcelFile(file, { region, worker, belongingRegion, month });
      setPreview(results.map(r => ({ ...r, id: generateId() })));
    } catch (err: any) {
      alert("解析失敗: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  const confirmImport = () => {
    onImport(preview);
    setPreview([]);
    setFile(null);
    alert("已匯入至本地資料庫，請至「紀錄查詢」同步雲端。");
  };

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
      <div className="p-8 border-b border-slate-100 bg-slate-50/30">
        <h2 className="text-xl font-bold">批次匯入撥款名冊</h2>
      </div>
      <div className="p-8 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="space-y-1">
          <label className="text-[10px] font-bold text-slate-400 uppercase">區域</label>
          <select className="w-full bg-slate-50 border rounded-xl px-3 py-2 text-sm outline-none" value={region} onChange={(e) => setRegion(e.target.value)}>
            {options.regions.map(r => <option key={r} value={r}>{r}</option>)}
          </select>
        </div>
        <div className="space-y-1">
