          <button onClick={generateAIInsight} disabled={loadingInsight || records.length === 0} className="text-xs bg-indigo-50 text-indigo-600 px-4 py-2 rounded-full font-bold hover:bg-indigo-100 transition-all disabled:opacity-50">
