        </div>
        {loadingInsight ? (
          <div className="flex flex-col items-center py-10"><Loader2 className="animate-spin text-indigo-500 mb-2" /><p className="text-sm text-slate-500">正在處理數據...</p></div>
        ) : insight ? (
          <div className="bg-slate-50 p-6 rounded-2xl text-slate-700 whitespace-pre-wrap text-sm border border-slate-100 leading-relaxed font-medium">{insight}</div>
        ) : (
