};

// --- Login Screen ---
const LoginScreen = ({ onLogin }: { onLogin: () => void }) => {
  const [pass, setPass] = useState('');
  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-md p-10 rounded-[2.5rem] shadow-2xl text-center">
        <div className="inline-block p-5 bg-indigo-600 rounded-3xl text-white mb-6 shadow-xl shadow-indigo-100"><CheckCircle2 size={32} /></div>
        <h1 className="text-2xl font-black text-slate-900 mb-8 uppercase tracking-widest">NGO Access</h1>
        <form onSubmit={e => { e.preventDefault(); pass === '2025ngo' ? onLogin() : alert("密碼錯誤"); }} className="space-y-6">
          <input type="password" placeholder="••••" className="w-full px-4 py-5 rounded-2xl bg-slate-50 border border-slate-100 text-center text-xl font-bold outline-none focus:ring-4 focus:ring-indigo-500/10" value={pass} onChange={e => setPass(e.target.value)}/>
          <button type="submit" className="w-full bg-indigo-600 text-white py-5 rounded-2xl font-bold text-lg hover:shadow-2xl transition-all">進入核銷系統</button>
        </form>
      </div>
    </div>
  );
};

// --- App Root ---
function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.DASHBOARD);
  const [records, setRecords] = useState<SubsidyRecord[]>(() => JSON.parse(localStorage.getItem('ngo_records') || '[]'));
  const [options, setOptions] = useState<NGOOptions>(() => JSON.parse(localStorage.getItem('ngo_settings') || JSON.stringify(NGO_CONFIG)));

  useEffect(() => localStorage.setItem('ngo_records', JSON.stringify(records)), [records]);
  useEffect(() => localStorage.setItem('ngo_settings', JSON.stringify(options)), [options]);
  useEffect(() => setIsLoggedIn(localStorage.getItem('ngo_auth') === 'true'), []);

  if (!isLoggedIn) return <LoginScreen onLogin={() => { setIsLoggedIn(true); localStorage.setItem('ngo_auth', 'true'); }} />;

  const NavWatcher = ({ tab }: { tab: AppTab }) => { useEffect(() => setActiveTab(tab), [tab]); return null; };

  return (
    <HashRouter>
      <div className="flex min-h-screen bg-slate-50 font-['Inter']">
        <Sidebar activeTab={activeTab} onLogout={() => { setIsLoggedIn(false); localStorage.removeItem('ngo_auth'); }} />
        <main className="flex-1 ml-64 p-8">
          <header className="mb-8 flex justify-between items-center border-b pb-6 border-slate-200">
            <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tight">{activeTab}</h1>
            <div className={`px-4 py-1.5 rounded-full text-[10px] font-bold border flex items-center gap-1.5 ${options.syncUrl ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'bg-slate-100 text-slate-400 border-slate-200'}`}>
              {options.syncUrl ? <CloudCheck size={12}/> : <CloudOff size={12}/>}
              {options.syncUrl ? 'SYNC ACTIVE' : 'LOCAL MODE'}
            </div>
          </header>
          <Routes>
            <Route path="/dashboard" element={<><NavWatcher tab={AppTab.DASHBOARD}/><Dashboard records={records}/></>} />
            <Route path="/import" element={<><NavWatcher tab={AppTab.IMPORT}/><ImportTab onImport={r => setRecords(p => [...r, ...p])} options={options}/></>} />
            <Route path="/manual" element={<><NavWatcher tab={AppTab.MANUAL}/><ManualEntry onAdd={r => setRecords(p => [r, ...p])} options={options}/></>} />
            <Route path="/records" element={<><NavWatcher tab={AppTab.RECORDS}/><RecordsTable records={records} onDelete={id => setRecords(p => p.filter(x => x.id !== id))} onClearAll={() => setRecords([])} syncUrl={options.syncUrl}/></>} />
            <Route path="/settings" element={<><NavWatcher tab={AppTab.SETTINGS}/><SettingsPage options={options} setOptions={setOptions}/></>} />
            <Route path="*" element={<Navigate to="/dashboard" replace />} />
          </Routes>
        </main>
      </div>
    </HashRouter>
  );
}

export default App;

