// --- Import Tab ---
const ImportTab = ({ onImport, options }: { onImport: (newRecords: SubsidyRecord[]) => void, options: NGOOptions }) => {
  const [file, setFile] = useState<File | null>(null);
  const [region, setRegion] = useState(options.regions[0] || '');
  const [worker, setWorker] = useState(options.workers[0] || '');
  const [month, setMonth] = useState(new Date().toISOString().slice(0, 7));
  const [loading, setLoading] = useState(false);
  const [preview, setPreview] = useState<SubsidyRecord[]>([]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) setFile(e.target.files[0]);
  };

  const processFile = async () => {
    if (!file) return;
    setLoading(true);
    try {
      const results = await parseExcelFile(file, { region, worker, month });
      setPreview(results.map(r => ({ ...r, id: generateId() })));
    } catch (err: any) {
      alert("解析失敗: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  const confirmImport = () => {
    onImport(preview);
    setPreview([]);
    setFile(null);
    alert("匯入成功！請切換至「紀錄查詢」同步雲端。");
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden max-w-4xl mx-auto">
      <div className="p-8 border-b border-slate-100 bg-slate-50/30">
        <h2 className="text-xl font-bold flex items-center gap-2 tracking-tight">
          <div className="p-2 bg-indigo-100 rounded-lg text-indigo-600"><FileUp size={20} /></div>
          批次匯入撥款名冊
        </h2>
      </div>
      <div className="p-8 grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-1.5">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">執行區域</label>
          <select className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 font-medium" value={region} onChange={e => setRegion(e.target.value)}>
            {options.regions.map(r => <option key={r} value={r}>{r}</option>)}
          </select>
        </div>
        <div className="space-y-1.5">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">主辦社工</label>
          <select className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 font-medium" value={worker} onChange={e => setWorker(e.target.value)}>
            {options.workers.map(w => <option key={w} value={w}>{w}</option>)}
          </select>
        </div>
        <div className="space-y-1.5">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">撥款月份</label>
          <input type="month" className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 font-medium" value={month} onChange={e => setMonth(e.target.value)} />
        </div>
      </div>
      <div className="px-8 pb-8">
        <div className="border-3 border-dashed border-slate-200 rounded-[2rem] p-16 text-center bg-slate-50/50 hover:bg-slate-50/80 hover:border-indigo-300 cursor-pointer transition-all group">
          <input type="file" id="excel-upload" className="hidden" accept=".xlsx, .xls" onChange={handleFileChange}/>
          <label htmlFor="excel-upload" className="cursor-pointer flex flex-col items-center">
            <div className="w-16 h-16 bg-white rounded-2xl shadow-sm flex items-center justify-center mb-6 group-hover:scale-110 transition-transform border border-slate-100">
              <FileUp size={32} className="text-indigo-500" />
            </div>
            <p className="text-slate-900 font-bold text-lg">{file ? file.name : '點擊或拖入 Excel 名冊'}</p>
            <p className="text-slate-400 text-xs mt-2 font-medium">支援格式: .xlsx, .xls (總表欄位需包含姓名、項目、各來源金額)</p>
          </label>
        </div>
        {file && !preview.length && (
          <button onClick={processFile} disabled={loading} className="mt-8 w-full bg-indigo-600 text-white py-5 rounded-[1.5rem] font-bold flex items-center justify-center gap-3 hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100">
            {loading ? <Loader2 className="animate-spin" /> : <Sparkles size={22}/>}
            {loading ? '正在分析結構與金額...' : '開始解析名冊數據'}
          </button>
        )}
      </div>
      {preview.length > 0 && (
        <div className="p-8 bg-slate-900 border-t border-slate-800 animate-in slide-in-from-bottom duration-500">
          <div className="flex items-center justify-between mb-6">
            <h3 className="font-bold flex items-center gap-2 text-white text-lg">
              <ClipboardCheck className="text-emerald-400" /> 
              預覽解析結果 ({preview.length} 筆)
            </h3>
            <div className="flex gap-3">
              <button onClick={() => setPreview([])} className="bg-slate-800 text-slate-400 px-6 py-2.5 rounded-xl border border-slate-700 font-bold hover:bg-slate-700">取消</button>
              <button onClick={confirmImport} className="bg-emerald-500 text-white px-8 py-2.5 rounded-xl font-bold shadow-lg shadow-emerald-500/20 hover:bg-emerald-400">確認並匯入本地</button>
            </div>
          </div>
          <div className="max-h-80 overflow-y-auto rounded-2xl border border-slate-800 bg-slate-900 no-scrollbar shadow-inner">
            <table className="w-full text-xs text-slate-300">
              <thead className="bg-slate-800 sticky top-0 border-b border-slate-700">
                <tr><th className="p-4 text-left font-bold uppercase tracking-widest text-slate-500">姓名</th><th className="p-4 text-left font-bold uppercase tracking-widest text-slate-500">項目</th><th className="p-4 text-right font-bold uppercase tracking-widest text-slate-500">金額</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-800">
                {preview.map((r, i) => (
                  <tr key={i} className="hover:bg-slate-800/50 transition-colors">
                    <td className="p-4 font-bold text-white">{r.clientName}</td>
                    <td className="p-4 text-slate-400">{r.item}</td>
                    <td className="p-4 text-right font-bold text-indigo-400 text-sm">${r.amount.toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

// --- Records Table ---
const RecordsTable = ({ records, onDelete, onClearAll, syncUrl }: { records: SubsidyRecord[], onDelete: (id: string) => void, onClearAll: () => void, syncUrl?: string }) => {
  const [syncing, setSyncing] = useState(false);

  const handleSync = async () => {
    if (!syncUrl) return alert("請至「系統設定」貼上 Google Apps Script 網址。");
    setSyncing(true);
    const success = await syncToGoogleSheets(syncUrl, records);
    setSyncing(false);
    if (success) {
      alert("同步完成！雲端試算表已更新。");
    } else {
      alert("同步過程出現錯誤，請檢查 GAS 部署是否正確。");
    }
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden animate-in fade-in duration-500">
      <div className="p-8 border-b flex flex-col md:flex-row justify-between items-start md:items-center bg-slate-50/50 gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">核銷紀錄清單</h2>
          <p className="text-slate-500 text-xs font-medium mt-1">目前本地庫存有 {records.length} 筆待同步資料。</p>
        </div>
        <div className="flex gap-3">
          {records.length > 0 && (
            <>
              <button 
                onClick={handleSync} 
                disabled={syncing} 
                className="flex items-center gap-2 px-6 py-3 bg-emerald-600 text-white rounded-[1.2rem] text-sm font-bold shadow-lg shadow-emerald-200 hover:bg-emerald-700 active:scale-95 transition-all disabled:opacity-50"
              >
                {syncing ? <Loader2 size={18} className="animate-spin" /> : <CloudUpload size={18} />} 
                {syncing ? '同步中...' : '同步至雲端'}
              </button>
              <button 
                onClick={() => window.confirm("確定要清空所有本地資料嗎？此操作不可恢復。") && onClearAll()} 
                className="p-3 text-red-500 hover:bg-red-50 rounded-xl transition-colors border border-transparent hover:border-red-100"
                title="清空本地"
              >
                <RotateCcw size={20}/>
              </button>
            </>
          )}
        </div>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead className="bg-slate-50 text-slate-400 font-bold uppercase tracking-widest text-[10px]">
            <tr>
              <th className="px-8 py-5 text-left">姓名</th>
              <th className="px-8 py-5 text-left">核銷項目</th>
              <th className="px-8 py-5 text-left">經費來源</th>
              <th className="px-8 py-5 text-right">金額</th>
              <th className="px-8 py-5 text-center">操作</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {records.length === 0 ? (
              <tr><td colSpan={5} className="p-20 text-center text-slate-300 font-medium">目前暫無核銷資料，請由「匯入」或「補登」開始。</td></tr>
            ) : (
              records.map(r => (
                <tr key={r.id} className="hover:bg-slate-50/80 transition-colors group">
                  <td className="px-8 py-5 font-bold text-slate-900">{r.clientName}</td>
                  <td className="px-8 py-5 text-slate-600 font-medium">{r.item}</td>
                  <td className="px-8 py-5">
                    <span className="bg-indigo-50 text-indigo-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider border border-indigo-100">
                      {r.source}
                    </span>
                  </td>
                  <td className="px-8 py-5 text-right font-black text-slate-900 text-base">${r.amount.toLocaleString()}</td>
                  <td className="px-8 py-5 text-center">
                    <button 
                      onClick={() => onDelete(r.id)} 
                      className="p-2 text-slate-300 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-all"
                    >
                      <Trash2 size={18}/>
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
