          <p className="text-slate-400 text-xs font-black uppercase tracking-[0.2em]">Service Clients</p>
          <p className="text-4xl font-black text-slate-900 mt-3 group-hover:text-indigo-600 transition-colors">{stats.clients}</p>
          <p className="text-[10px] font-bold text-slate-400 mt-4 flex items-center gap-2">服務個案總人數</p>
