// --- App Root ---
function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.DASHBOARD);
  const [records, setRecords] = useState<SubsidyRecord[]>(() => JSON.parse(localStorage.getItem('ngo_records') || '[]'));
  const [options, setOptions] = useState<NGOOptions>(() => JSON.parse(localStorage.getItem('ngo_settings') || JSON.stringify(NGO_CONFIG)));

  useEffect(() => localStorage.setItem('ngo_records', JSON.stringify(records)), [records]);
  useEffect(() => localStorage.setItem('ngo_settings', JSON.stringify(options)), [options]);
  useEffect(() => setIsLoggedIn(localStorage.getItem('ngo_auth') === 'true'), []);

  if (!isLoggedIn) return <LoginScreen onLogin={() => { setIsLoggedIn(true); localStorage.setItem('ngo_auth', 'true'); }} />;

  const NavWatcher = ({ tab }: { tab: AppTab }) => { useEffect(() => setActiveTab(tab), [tab]); return null; };

  return (
    <HashRouter>
      <div className="flex min-h-screen bg-[#F8FAFC] font-['Inter'] selection:bg-indigo-100">
        <Sidebar activeTab={activeTab} onLogout={() => { setIsLoggedIn(false); localStorage.removeItem('ngo_auth'); }} />
        <main className="flex-1 ml-64 p-10">
          <header className="mb-10 flex flex-col md:flex-row justify-between items-start md:items-end gap-4 border-b border-slate-200 pb-8">
            <div>
              <div className="flex items-center gap-2 mb-1">
                <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse"></div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Workspace</span>
              </div>
              <h1 className="text-4xl font-black text-slate-900 uppercase tracking-tighter">{activeTab}</h1>
            </div>
            <div className={`px-5 py-2 rounded-2xl text-[10px] font-black tracking-widest border flex items-center gap-2 transition-all shadow-sm ${options.syncUrl ? 'bg-emerald-50 text-emerald-600 border-emerald-100 shadow-emerald-500/5' : 'bg-slate-100 text-slate-400 border-slate-200'}`}>
              {options.syncUrl ? <CloudCheck size={14}/> : <CloudOff size={14}/>}
              {options.syncUrl ? 'CLOUD SYNC READY' : 'LOCAL OFFLINE MODE'}
            </div>
          </header>

          <div className="max-w-[1200px]">
            <Routes>
              <Route path="/dashboard" element={<><NavWatcher tab={AppTab.DASHBOARD}/><Dashboard records={records}/></>} />
              <Route path="/import" element={<><NavWatcher tab={AppTab.IMPORT}/><ImportTab onImport={r => setRecords(p => [...r, ...p])} options={options}/></>} />
              <Route path="/manual" element={<><NavWatcher tab={AppTab.MANUAL}/><ManualEntry onAdd={r => setRecords(p => [r, ...p])} options={options}/></>} />
              <Route path="/records" element={<><NavWatcher tab={AppTab.RECORDS}/><RecordsTable records={records} onDelete={id => setRecords(p => p.filter(x => x.id !== id))} onClearAll={() => setRecords([])} syncUrl={options.syncUrl}/></>} />
              <Route path="/settings" element={<><NavWatcher tab={AppTab.SETTINGS}/><SettingsPage options={options} setOptions={setOptions}/></>} />
              <Route path="*" element={<Navigate to="/dashboard" replace />} />
            </Routes>
          </div>
        </main>
      </div>
    </HashRouter>
  );
}

export default App;

