          <div className="flex flex-wrap gap-2">
            {columnOrder.map((col, i) => (
              <div key={i} className="bg-white border border-slate-200 px-3 py-2 rounded-xl text-xs font-semibold shadow-sm">
                <span className="text-indigo-500 font-bold mr-2">{String.fromCharCode(65 + i)}</span>
                <span className="text-slate-700">{col}</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {sections.map(section => (
          <div key={section.key} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col h-full">
