            {options.regions.map(r => <option key={r} value={r}>{r}</option>)}
          </select>
        </div>
        <div className="space-y-1.5">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">主辦社工</label>
          <select className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 font-medium" value={worker} onChange={e => setWorker(e.target.value)}>
            {options.workers.map(w => <option key={w} value={w}>{w}</option>)}
          </select>
        </div>
        <div className="space-y-1.5">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">撥款月份</label>
          <input type="month" className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 font-medium" value={month} onChange={e => setMonth(e.target.value)} />
        </div>
      </div>
      <div className="px-8 pb-8">
