        <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 group">
          <p className="text-slate-400 text-xs font-black uppercase tracking-[0.2em]">Sources</p>
          <p className="text-4xl font-black text-slate-900 mt-3 group-hover:text-indigo-600 transition-colors">{stats.sources}</p>
