                value={inputValues[section.key] || ''}
                onChange={(e) => setInputValues({...inputValues, [section.key]: e.target.value})}
                onKeyDown={(e) => e.key === 'Enter' && addItem(section.key as keyof NGOOptions)}
              />
              <button onClick={() => addItem(section.key as keyof NGOOptions)} className="bg-indigo-600 text-white p-2 rounded-xl hover:bg-indigo-700 transition-colors">
                <Plus size={18}/>
              </button>
            </div>
