// --- Dashboard ---
const Dashboard = ({ records }: { records: SubsidyRecord[] }) => {
  const totalAmount = useMemo(() => records.reduce((sum, r) => sum + r.amount, 0), [records]);
  const [insight, setInsight] = useState<string>('');
  const [loadingInsight, setLoadingInsight] = useState(false);
  const [copied, setCopied] = useState(false);

  const generateAIInsight = async () => {
    if (records.length === 0) return;
    setLoadingInsight(true);
    setInsight(await getFinancialInsights(records));
    setLoadingInsight(false);
  };

  const copyToClipboard = () => {
    if (!insight) return;
    navigator.clipboard.writeText(insight);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-8 text-indigo-100 group-hover:text-indigo-200 transition-colors"><CloudUpload size={80}/></div>
          <p className="text-slate-400 text-xs font-black uppercase tracking-[0.2em] relative z-10">Total Amount</p>
          <p className="text-4xl font-black text-indigo-600 mt-3 relative z-10">${totalAmount.toLocaleString()}</p>
        </div>
      </div>
      <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-slate-100">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-black flex items-center gap-3 text-slate-900 tracking-tight">AI 財務洞察</h2>
          <button onClick={generateAIInsight} disabled={loadingInsight || records.length === 0} className="text-xs bg-indigo-600 text-white px-6 py-3 rounded-2xl font-black hover:bg-indigo-700 disabled:opacity-50 transition-all">
            {loadingInsight ? '正在生成...' : '生成報告'}
          </button>
        </div>
        {insight && (
          <div className="bg-slate-50 p-6 rounded-2xl relative group border border-slate-100">
            <button onClick={copyToClipboard} className="absolute top-4 right-4 p-2 bg-white rounded-lg shadow-sm hover:bg-slate-50 border border-slate-100">
              {copied ? <Check size={16} className="text-emerald-500"/> : <Copy size={16} className="text-slate-400"/>}
            </button>
            <div className="text-slate-700 whitespace-pre-wrap text-sm leading-relaxed">{insight}</div>
          </div>
        )}
      </div>
    </div>
  );
};

