// --- App Root ---
function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.DASHBOARD);
  const [records, setRecords] = useState<SubsidyRecord[]>(() => {
    const saved = localStorage.getItem('ngo_records');
    return saved ? JSON.parse(saved) : [];
  });
  const [options, setOptions] = useState<NGOOptions>(() => {
    const saved = localStorage.getItem('ngo_settings');
    return saved ? JSON.parse(saved) : NGO_CONFIG;
  });

  useEffect(() => localStorage.setItem('ngo_records', JSON.stringify(records)), [records]);
  useEffect(() => localStorage.setItem('ngo_settings', JSON.stringify(options)), [options]);
  useEffect(() => {
    const auth = localStorage.getItem('ngo_auth');
    if (auth === 'true') setIsLoggedIn(true);
  }, []);

  const handleLogin = () => {
    setIsLoggedIn(true);
    localStorage.setItem('ngo_auth', 'true');
  };

  if (!isLoggedIn) return <LoginScreen onLogin={handleLogin} />;

  const NavWatcher = ({ tab }: { tab: AppTab }) => { useEffect(() => setActiveTab(tab), [tab]); return null; };

  return (
    <HashRouter>
      <div className="flex min-h-screen bg-[#F8FAFC]">
        <Sidebar activeTab={activeTab} onLogout={() => { setIsLoggedIn(false); localStorage.removeItem('ngo_auth'); }} />
        <main className="flex-1 ml-64 p-10">
          <header className="mb-10 flex flex-col md:flex-row justify-between items-start md:items-end gap-4 border-b border-slate-200 pb-8">
            <div>
              <div className="flex items-center gap-2 mb-1 uppercase tracking-widest text-[10px] font-black text-slate-400">Workspace</div>
              <h1 className="text-4xl font-black text-slate-900 uppercase tracking-tighter">{activeTab}</h1>
            </div>
            <div className={`px-5 py-2 rounded-2xl text-[10px] font-black tracking-widest border flex items-center gap-2 transition-all ${options.syncUrl ? 'bg-emerald-50 text-emerald-600 border-emerald-100 shadow-sm shadow-emerald-500/5' : 'bg-slate-100 text-slate-400 border-slate-200'}`}>
              {options.syncUrl ? <CloudCheck size={14}/> : <CloudOff size={14}/>}
              {options.syncUrl ? 'CLOUD SYNC ON' : 'OFFLINE MODE'}
            </div>
          </header>

          <div className="max-w-[1200px]">
            <Routes>
              <Route path="/dashboard" element={<><NavWatcher tab={AppTab.DASHBOARD}/><Dashboard records={records}/></>} />
              <Route path="/import" element={<><NavWatcher tab={AppTab.IMPORT}/><ImportTab onImport={r => setRecords(p => [...r, ...p])} options={options}/></>} />
              <Route path="/manual" element={<><NavWatcher tab={AppTab.MANUAL}/><ManualEntry onAdd={r => setRecords(p => [r, ...p])} options={options}/></>} />
              <Route path="/records" element={<><NavWatcher tab={AppTab.RECORDS}/><RecordsTable records={records} onDelete={id => setRecords(p => p.filter(x => x.id !== id))} onClearAll={() => setRecords([])} syncUrl={options.syncUrl}/></>} />
              <Route path="/settings" element={<><NavWatcher tab={AppTab.SETTINGS}/><SettingsPage options={options} setOptions={setOptions}/></>} />
              <Route path="*" element={<Navigate to="/dashboard" replace />} />
            </Routes>
          </div>
        </main>
      </div>
    </HashRouter>
  );
}

const ImportTab = ({ onImport, options }: { onImport: (newRecords: SubsidyRecord[]) => void, options: NGOOptions }) => {
  const [file, setFile] = useState<File | null>(null);
  const [region, setRegion] = useState(options.regions[0] || '');
  const [worker, setWorker] = useState(options.workers[0] || '');
  const [month, setMonth] = useState(new Date().toISOString().slice(0, 7));
  const [loading, setLoading] = useState(false);
  const [preview, setPreview] = useState<SubsidyRecord[]>([]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) setFile(e.target.files[0]);
  };

  const processFile = async () => {
    if (!file) return;
    setLoading(true);
    try {
      const results = await parseExcelFile(file, { region, worker, month });
      setPreview(results.map(r => ({ ...r, id: generateId() })));
    } catch (err: any) {
      alert("解析失敗: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  const confirmImport = () => {
    onImport(preview);
    setPreview([]);
    setFile(null);
    alert("匯入成功！");
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden max-w-4xl mx-auto">
      <div className="p-8 border-b border-slate-100 bg-slate-50/30">
        <h2 className="text-xl font-bold flex items-center gap-2 tracking-tight">批次匯入</h2>
      </div>
      <div className="p-8 grid grid-cols-1 md:grid-cols-3 gap-6">
        <select className="bg-slate-50 border p-4 rounded-2xl text-sm" value={region} onChange={e => setRegion(e.target.value)}>{options.regions.map(r => <option key={r} value={r}>{r}</option>)}</select>
        <select className="bg-slate-50 border p-4 rounded-2xl text-sm" value={worker} onChange={e => setWorker(e.target.value)}>{options.workers.map(w => <option key={w} value={w}>{w}</option>)}</select>
        <input type="month" className="bg-slate-50 border p-4 rounded-2xl text-sm" value={month} onChange={e => setMonth(e.target.value)} />
      </div>
      <div className="p-8">
        <div className="border-2 border-dashed border-slate-200 p-12 text-center rounded-3xl bg-slate-50/50">
          <input type="file" id="up" className="hidden" onChange={handleFileChange} />
          <label htmlFor="up" className="cursor-pointer">
            <p className="text-slate-600 font-bold">{file ? file.name : "選擇 Excel 檔案"}</p>
          </label>
        </div>
        {file && <button onClick={processFile} disabled={loading} className="w-full mt-4 bg-indigo-600 text-white p-4 rounded-2xl font-bold">{loading ? "分析中..." : "開始解析"}</button>}
      </div>
      {preview.length > 0 && (
        <div className="p-8 bg-slate-900">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-white font-bold">預覽結果 ({preview.length} 筆)</h3>
            <button onClick={confirmImport} className="bg-emerald-500 text-white px-6 py-2 rounded-xl font-bold">確認匯入</button>
          </div>
          <div className="max-h-60 overflow-y-auto rounded-xl bg-slate-800 p-4">
             {preview.slice(0, 10).map((p, i) => <div key={i} className="text-slate-300 text-xs py-1 border-b border-slate-700">{p.clientName} - {p.item} (${p.amount})</div>)}
          </div>
        </div>
      )}
    </div>
  );
};

const RecordsTable = ({ records, onDelete, onClearAll, syncUrl }: { records: SubsidyRecord[], onDelete: (id: string) => void, onClearAll: () => void, syncUrl?: string }) => {
  const [syncing, setSyncing] = useState(false);

  const handleSync = async () => {
    if (!syncUrl) return alert("請至設定配置 GAS URL");
    setSyncing(true);
    const success = await syncToGoogleSheets(syncUrl, records);
    setSyncing(false);
    alert(success ? "同步完成" : "同步失敗");
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100">
      <div className="p-8 border-b flex justify-between items-center">
        <h2 className="text-2xl font-black">核銷紀錄</h2>
        <div className="flex gap-2">
          <button onClick={handleSync} disabled={syncing} className="bg-emerald-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2">
            {syncing ? <Loader2 className="animate-spin" size={16}/> : <CloudUpload size={16}/>}
            同步雲端
          </button>
          <button onClick={onClearAll} className="p-2 text-red-500"><RotateCcw size={20}/></button>
        </div>
      </div>
      <table className="w-full text-sm">
        <thead className="bg-slate-50 text-slate-400 text-xs uppercase">
          <tr><th className="p-6 text-left">姓名</th><th className="p-6 text-left">項目</th><th className="p-6 text-right">金額</th><th className="p-6 text-center">操作</th></tr>
        </thead>
        <tbody className="divide-y divide-slate-50">
          {records.map(r => (
            <tr key={r.id}>
              <td className="p-6 font-bold">{r.clientName}</td>
              <td className="p-6 text-slate-600">{r.item}</td>
              <td className="p-6 text-right font-black text-indigo-600">${r.amount}</td>
              <td className="p-6 text-center"><button onClick={() => onDelete(r.id)}><Trash2 size={16}/></button></td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default App;

