    const success = await syncToGoogleSheets(syncUrl, records);
    setSyncing(false);
    alert(success ? "雲端同步成功！" : "同步失敗，請檢查網路或網址。");
  };

  return (
    <div className="bg-white rounded-[2rem] shadow-sm border overflow-hidden">
