          {!isKeyMissing && (
            <button 
              onClick={generateAI} 
              disabled={loading || records.length === 0} 
              className="bg-indigo-600 text-white px-6 py-2 rounded-2xl text-xs font-bold shadow-lg hover:bg-indigo-700 disabled:opacity-50"
            >
              {loading ? '分析中...' : '生成趨勢報告'}
