          )}
        </div>

        {isKeyMissing ? (
          <div className="text-center py-16 bg-indigo-50 rounded-2xl border border-indigo-100 flex flex-col items-center gap-4">
            <div className="p-4 bg-white rounded-full text-indigo-600 shadow-sm">
